const waveCanvas=$('#waveCanvas'),wctx=waveCanvas.getContext('2d');function drawWave(now){const rect=waveCanvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2),w=Math.max(2,rect.width),h=Math.max(2,rect.height);if(waveCanvas.width!==Math.round(w*dpr)||waveCanvas.height!==Math.round(h*dpr)){waveCanvas.width=Math.round(w*dpr);waveCanvas.height=Math.round(h*dpr)}wctx.setTransform(dpr,0,0,dpr,0,0);wctx.clearRect(0,0,w,h);wctx.beginPath();const active=state.running&&state.audio,amp=active?Math.min(1,state.rpm/2200):.025,cycles=2+state.rpm/410;for(let x=0;x<w;x++){const t=x/w*cycles*Math.PI*2+now*.004;let val=Math.sin(t)*.5+Math.sin(t*2.9+.3)*.2+Math.sin(t*5.7+1)*.09;val*=amp;const y=h*.53-val*h*.85+(Math.random()-.5)*(active?.03:0);x===0?wctx.moveTo(x,y):wctx.lineTo(x,y)}wctx.strokeStyle=active?'#d1ff44':'#697267';wctx.lineWidth=1.5;wctx.shadowColor=active?'#d1ff44':'transparent';wctx.shadowBlur=active?8:0;wctx.stroke();wctx.shadowBlur=0;}
let audioCtx=null,master=null,osc1=null,osc2=null,noiseNode=null,noiseGain=null,filter=null,subGain=null;function setupAudio(){if(audioCtx)return;audioCtx=new (window.AudioContext||window.webkitAudioContext)();master=audioCtx.createGain();master.gain.value=.0001;master.connect(audioCtx.destination);osc1=audioCtx.createOscillator();osc2=audioCtx.createOscillator();osc1.type='sawtooth';osc2.type='triangle';const g1=audioCtx.createGain(),g2=audioCtx.createGain();g1.gain.value=.26;g2.gain.value=.12;osc1.connect(g1).connect(master);osc2.connect(g2).connect(master);osc1.start();osc2.start();const buffer=audioCtx.createBuffer(1,audioCtx.sampleRate*2,audioCtx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.75;noiseNode=audioCtx.createBufferSource();noiseNode.buffer=buffer;noiseNode.loop=true;filter=audioCtx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=300;noiseGain=audioCtx.createGain();noiseGain.gain.value=.22;noiseNode.connect(filter).connect(noiseGain).connect(master);noiseNode.start();subGain=audioCtx.createGain();subGain.gain.value=.13;const sub=audioCtx.createOscillator();sub.type='sine';sub.frequency.value=42;sub.connect(subGain).connect(master);sub.start();}
function updateAudio(){if(!audioCtx)return;const now=audioCtx.currentTime;const running=state.running&&state.audio;const rpm=running?Math.max(state.rpm,models[state.engine].idle):0;const firing=rpm*models[state.engine].cyl/120;osc1.frequency.setTargetAtTime(Math.max(20,firing),now,.07);osc2.frequency.setTargetAtTime(Math.max(20,firing*2.015),now,.07);filter.frequency.setTargetAtTime(190+state.throttle*18+rpm*.1+(state.induction==='boost'?600:0),now,.1);master.gain.setTargetAtTime(running?.22:0.0001,now,.18);noiseGain.gain.setTargetAtTime(running?.08+state.throttle*.002:0,now,.15);subGain.gain.setTargetAtTime(running?.10:0,now,.15);}
function updateControls(){for(const id of ['throttle','load','mixture']){const el=$('#'+id),pct=(el.value-el.min)/(el.max-el.min)*100;el.parentElement.style.setProperty('--pct',pct+'%')}$('#throttleOut').innerHTML=`${state.throttle}<span class="unit"> %</span>`;$('#loadOut').innerHTML=`${state.load}<span class="unit"> %</span>`;$('#mixOut').innerHTML=`${state.mix.toFixed(1)}<span class="unit"> : 1</span>`;}
function updateUI(){const cfg=models[state.engine],rpm=Math.round(state.rpm),torque=state.running?Math.round(cfg.baseTorque*(.28+state.load*.008)*(1-Math.max(0,state.rpm/cfg.redline-.74)*.52)*(state.induction==='boost'?1.24:state.induction==='sport'?1.08:1)):0,power=Math.round(torque*rpm/9549),arc=$('#rpmArc'),length=arc.getTotalLength(),ratio=Math.min(state.rpm/cfg.redline,1);arc.style.strokeDasharray=length;arc.style.strokeDashoffset=length*(1-ratio);arc.style.stroke=ratio>.84?'#ff643e':'#d1ff44';$('#rpmText').textContent=(rpm/1000).toFixed(1);$('#torqueText').innerHTML=`${torque}<em>Nm</em>`;$('#powerText').innerHTML=`${power}<em>kW</em>`;$('#tempText').innerHTML=`${Math.round(state.temp)}<em>°C</em>`;$('#tempBar').style.width=`${Math.min(100,(state.temp-22)/1.05)}%`;$('#oilText').innerHTML=`${state.oil.toFixed(1)}<em>bar</em>`;$('#statusText').textContent=!state.running?'OFFLINE':state.rpm<cfg.idle+100?'IDLE':state.rpm>cfg.redline*.86?'REDLINE':'RUNNING';$('#statusText').classList.toggle('running',state.running);$('#startBtn').classList.toggle('running',state.running);$('#startLabel').textContent=state.running?'STOP ENGINE':'START ENGINE';$('#liveDot').classList.toggle('on',state.running);$('#liveLabel').textContent=state.running?'ENGINE ONLINE':'SYSTEM STANDBY';$('#waveMeta').textContent=state.running?`${Math.round(state.rpm*cfg.cyl/120)} Hz   ·   ${Math.round(state.rpm)} RPM`:'— — — —';$('#soundLabel').textContent=state.audio?'ACTIVE':'MUTED';$('#soundToggle').classList.toggle('on',state.audio);$('#soundInfo').innerHTML=state.audio?'Procedural combustion synthesis.<br>Live firing-order harmonics.':'Enable sound to hear your engine.<br>Headphones recommended.';$('#soundBars').classList.toggle('playing',state.audio&&state.running);updateAudio();}
function tick(now){const dt=Math.min(.05,(now-last)/1000);last=now;time=now;if(state.running){const cfg=models[state.engine],induction=state.induction==='boost'?1.2:state.induction==='sport'?1.08:1;const target=cfg.idle+(state.throttle/100)*(cfg.redline*.92-cfg.idle)*induction;state.rpm+=(target-state.rpm)*Math.min(1,dt*(target>state.rpm?2.8:1.55));state.rpm+=Math.sin(now*.0018)*state.throttle*.28;state.temp+=(78+state.throttle*.35-state.temp)*dt*.022;state.oil+=(1.2+state.rpm/1800-state.oil)*dt*2.1;}else{state.rpm+=(0-state.rpm)*Math.min(1,dt*4);state.temp+=(22-state.temp)*dt*.035;state.oil+=(0-state.oil)*dt*4;}if(sceneReady){const speed=state.running?state.rpm/60:0;for(const p of pistonMeshes){const phase=now*.001*speed*2*Math.PI+p.phase;const stroke=Math.cos(phase)*.24;p.piston.position.y=.17+stroke;p.piston.children[0].rotation.z=Math.sin(phase)*.08;}flywheel.rotation.z+=dt*speed*.42;engineRoot.rotation.y=-.12+Math.sin(now*.0018)*Math.min(state.rpm/9000,.035);engineRoot.position.y=state.running?Math.sin(now*.006)*Math.min(state.rpm/1000,.018):0;cloud.rotation.y=now*.000025;renderer.render(scene,camera)}drawWave(now);if(Math.floor(now/140)%2===0)updateUI();requestAnimationFrame(tick)}
function startStop(){if(state.running){state.running=false;state.throttle=0;$('#throttle').value=0}else{state.running=true;if(state.rpm<models[state.engine].idle*.7)state.rpm=models[state.engine].idle*.72}updateControls();updateUI()}
$('#startBtn').addEventListener('click',startStop);$('#resetBtn').addEventListener('click',()=>{state.running=false;state.throttle=0;state.load=24;state.mix=14.7;state.rpm=0;state.temp=22;state.oil=0;$('#throttle').value=0;$('#load').value=24;$('#mixture').value=147;updateControls();updateUI()});$('#throttle').addEventListener('input',e=>{state.throttle=+e.target.value;if(state.throttle>0&&!state.running){state.running=true;state.rpm=models[state.engine].idle*.85}updateControls();updateUI()});$('#load').addEventListener('input',e=>{state.load=+e.target.value;updateControls();updateUI()});$('#mixture').addEventListener('input',e=>{state.mix=+e.target.value/10;updateControls()});$$('.engine-card').forEach(b=>b.addEventListener('click',()=>{$$('.engine-card').forEach(x=>x.classList.toggle('active',x===b));state.engine=b.dataset.engine;state.rpm=state.running?models[state.engine].idle:0;if(sceneReady)addEngine(state.engine);updateUI()}));$$('.mode-btn').forEach(b=>b.addEventListener('click',()=>{$$('.mode-btn').forEach(x=>x.classList.toggle('active',x===b));state.induction=b.dataset.induction;$('#inductionLabel').textContent=b.dataset.induction.toUpperCase();updateUI()}));$('#soundToggle').addEventListener('click',async()=>{if(!state.audio){setupAudio();await audioCtx.resume();state.audio=true;$('#soundToast').classList.remove('show')}else state.audio=false;updateUI()});window.addEventListener('keydown',e=>{if(e.code==='Space'&&e.target.tagName!=='INPUT'){e.preventDefault();startStop()}});window.addEventListener('resize',resize);updateControls();init3d();updateUI();requestAnimationFrame(tick);
</script>
