 <div class="control"><div class="control-head"><span>THROTTLE</span><output id="throttleOut">0<span class="unit"> %</span></output></div><div class="range-wrap"><input id="throttle" type="range" min="0" max="100" value="0"></div></div><div class="control"><div class="control-head"><span>ENGINE LOAD</span><output id="loadOut">24<span class="unit"> %</span></output></div><div class="range-wrap"><input id="load" type="range" min="0" max="100" value="24"></div></div><div class="control"><div class="control-head"><span>AIR / FUEL MIX</span><output id="mixOut">14.7<span class="unit"> : 1</span></output></div><div class="range-wrap"><input id="mixture" type="range" min="105" max="180" value="147"></div></div><div class="control modebox"><div class="control-head"><span>INDUCTION</span><output id="inductionLabel">NATURAL</output></div><div class="mode-row"><button class="mode-btn active" data-induction="natural">NA</button><button class="mode-btn" data-induction="sport">SPORT</button><button class="mode-btn" data-induction="boost">BOOST</button></div></div></aside>
 <section class="scene" aria-label="Interactive 3D engine"><canvas id="engine-canvas"></canvas><div class="scene-hud"><div class="scene-title" id="sceneTitle">5.2L CROSS-PLANE V8</div><div class="scene-caption">LIVE CUTAWAY · DRAG TO ORBIT · SCROLL TO ZOOM</div></div><div class="scene-badge"><i></i>PHYSICS CORE ACTIVE</div><div class="scene-controls"><span><b>DRAG</b> ORBIT</span><span><b>SCROLL</b> ZOOM</span><span><b>SPACE</b> IGNITION</span></div></section>
